-- Phase 4J: device-associated infection prevention knowledge.
insert into public.lira_knowledge_sources(organization_id,source_type,title,authority,source_url,source_version,language,status,metadata,ingestion_status)
values
(null,'guideline','Guidelines for the Prevention of Intravascular Catheter-Related Infections','CDC','https://www.cdc.gov/infection-control/hcp/intravascular-catheter-related-infection/index.html','current-reviewed-2026','en','review',jsonb_build_object('official',true,'topic','clabsi-prevention','review_required',true,'phase','4J'),'pending'),
