(null,'guideline','Strategies to prevent ventilator-associated pneumonia, ventilator-associated events, and nonventilator hospital-acquired pneumonia','SHEA/IDSA/APIC','https://www.cambridge.org/core/journals/infection-control-and-hospital-epidemiology/article/strategies-to-prevent-ventilatorassociated-pneumonia-ventilatorassociated-events-and-nonventilator-hospitalacquired-pneumonia-in-acute-care-hospitals-2022-update/','2022 update','en','review',jsonb_build_object('official',false,'expert_guidance',true,'topic','vap-vae-prevention','review_required',true,'phase','4J'),'pending')
